mod solution;

fn main() {
    let cases = [
    (r#"[(1,3),(2,6),(8,10),(9,12)]"#, r#"1-6,8-12"#),
    (r#"[(1,2),(3,4)]"#, r#"1-2,3-4"#),
    (r#"
[(1,2),(3,4)]
"#, r#"1-2,3-4"#),
    (r#"  
[(1,3),(2,6),(8,10),(9,12)]
  "#, r#"1-6,8-12"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS merge-intervals");
}
